  status, featured, meta_title, meta_description, keywords, reading_time,
  published_at, created_at, updated_at
)
select
  'How much heat does ceramic window film actually block?',
  'how-much-heat-does-ceramic-window-film-block',
  'We put a thermometer inside a parked car — with film, without film, at 45°C outside. The numbers are stark. Here''s what ceramic window film actually does to your cabin temperature.',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The question nobody answers directly"}]},{"type":"paragraph","content":[{"type":"text","text":"Every window film brand claims \"superior heat rejection.\" Almost none of them tell you what that looks like in practice — in your car, in an Indian summer, when the sun is straight overhead at 1 PM."}]},{"type":"paragraph","content":[{"type":"text","text":"So we measured it ourselves."}]},{"type":"paragraph","content":[{"type":"text","text":"We parked two identical sedans side-by-side on a concrete surface in Pune in May. Outside temperature: "},{"type":"text","marks":[{"type":"bold"}],"text":"45°C"},{"type":"text","text":". One car had SUNKOOL Foundation Series (ceramic, 35% VLT) applied to all windows. The other was unmodified factory glass. Both sat closed, no AC, for 90 minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"The results:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Measurement"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Unfilmed glass"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Foundation Series ceramic"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dashboard surface"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"82°C"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"49°C"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rear seat headrest"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"68°C"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"41°C"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Steering wheel rim"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"74°C"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"46°C"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Cabin air at seat level"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"61°C"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"37°C"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That''s not a small difference. The ceramic film dropped cabin air temperature by "},{"type":"text","marks":[{"type":"bold"}],"text":"24°C"},{"type":"text","text":" in the same conditions, same time, same sun angle."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What''s actually happening inside the film"}]},{"type":"paragraph","content":[{"type":"text","text":"Standard glass transmits visible light — that''s the point — but it also transmits a large portion of the solar spectrum you "},{"type":"text","marks":[{"type":"italic"}],"text":"can''t"},{"type":"text","text":" see: near-infrared (NIR), which runs roughly 700–2500 nm. NIR is responsible for about "},{"type":"text","marks":[{"type":"bold"}],"text":"53% of the total solar energy"},{"type":"text","text":" hitting your glass. Your eyes don''t detect it, but your skin and your dashboard do."}]},{"type":"paragraph","content":[{"type":"text","text":"Ceramic window film works by embedding nano-particles of non-conductive ceramic material (typically titanium nitride, silicon nitride, or similar compounds) into the adhesive and film layers. These particles are tuned — through a process called magnetron sputtering at our manufacturing level — to selectively absorb and reflect NIR while passing visible light through with minimal colour distortion."}]},{"type":"paragraph","content":[{"type":"text","text":"The metric that matters here is "},{"type":"text","marks":[{"type":"bold"}],"text":"Total Solar Energy Rejection (TSER)"},{"type":"text","text":". It''s a composite score accounting for:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct solar transmission through the glass"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Solar energy absorbed by the film and re-radiated inward"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reflected solar energy"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For SUNKOOL Foundation Series, TSER sits at "},{"type":"text","marks":[{"type":"bold"}],"text":"68%"},{"type":"text","text":" at 35% VLT. That means 68% of all solar energy — not just the visible part — is rejected before it enters the cabin."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why dyed film fails in summer"}]},{"type":"paragraph","content":[{"type":"text","text":"Dyed film (the cheap option) uses organic dyes embedded in a polyester layer. The dye absorbs solar energy — both visible and NIR — but absorption is not the same as rejection. Heat absorbed by the film is re-radiated in all directions, including back into the cabin through convection and the inner glass surface."}]},{"type":"paragraph","content":[{"type":"text","text":"This is why dyed films feel effective in mild weather (less total solar load to manage) but fail badly in peak summer. The film itself becomes a radiating surface at 60–70°C, and your AC fights it while you''re sitting next to it."}]},{"type":"paragraph","content":[{"type":"text","text":"Ceramic doesn''t absorb the way dye does — it reflects. Reflected energy goes back outside. The film stays cooler, the glass stays cooler, and your cabin stays cooler."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The AC math"}]},{"type":"paragraph","content":[{"type":"text","text":"A cooler cabin doesn''t just mean comfort. It means your AC compressor reaches the target temperature faster and cycles less."}]},{"type":"paragraph","content":[{"type":"text","text":"In EVs, this matters even more. Air conditioning is one of the biggest range consumers in an electric vehicle — particularly in a hot climate. HVAC loads in Indian summer conditions can account for "},{"type":"text","marks":[{"type":"bold"}],"text":"15–25% of total energy consumption"},{"type":"text","text":" on a charge. A cooler pre-conditioned cabin (or a cabin that doesn''t heat as severely while parked) directly extends your range per charge."}]},{"type":"paragraph","content":[{"type":"text","text":"Ceramic window film is not a luxury accessory in an Indian climate. It''s a thermal management layer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What VLT does and doesn''t tell you"}]},{"type":"paragraph","content":[{"type":"text","text":"VLT — Visible Light Transmission — is the number most people fixate on. 35% VLT means 35% of visible light passes through. That determines how dark the tint looks."}]},{"type":"paragraph","content":[{"type":"text","text":"But VLT tells you nothing about heat rejection. A film at 35% VLT could have a TSER of 40% (dyed, poor) or 68% (ceramic, excellent). The darkness looks the same. The performance is worlds apart."}]},{"type":"paragraph","content":[{"type":"text","text":"When you''re evaluating a film, ask for the "},{"type":"text","marks":[{"type":"bold"}],"text":"TSER"},{"type":"text","text":" number, the "},{"type":"text","marks":[{"type":"bold"}],"text":"IR rejection"},{"type":"text","text":" at specific wavelengths (particularly 800–1100 nm where the NIR load peaks), and whether the film uses ceramic or dyed technology."}]},{"type":"paragraph","content":[{"type":"text","text":"We publish all three numbers for every product in our "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/compare","target":"_blank","rel":"noopener noreferrer","class":null,"title":null}}],"text":"comparison tool"},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Does it fade over time?"}]},{"type":"paragraph","content":[{"type":"text","text":"Dyed film fades — the organic dyes degrade under UV exposure, which is exactly the environment they''re operating in. The film turns purple, the TSER drops, and within 3–5 years the performance of a cheap film is meaningfully worse than when it was installed."}]},{"type":"paragraph","content":[{"type":"text","text":"Ceramic nano-particles don''t degrade this way. They''re inorganic. The rejections you buy on day one are the rejections you have on day 1,000. This is why SUNKOOL backs ceramic film with a "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/warranty","target":"_blank","rel":"noopener noreferrer","class":null,"title":null}}],"text":"lifetime warranty"},{"type":"text","text":" against delamination, bubbling, colour change, and performance degradation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you should expect after installation"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Immediate effect"},{"type":"text","text":": The difference is noticeable from the first time you park in direct sun. Your hand on the window surface feels different — substantially less radiant heat."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"First week"},{"type":"text","text":": Allow 5–7 days for the adhesive to cure fully. Some haze or small bubbles during this period are normal and will clear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"AC usage"},{"type":"text","text":": Most of our customers report a subjective reduction in AC usage, particularly for short trips where the car hasn''t had time to fully pre-cool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Driving visibility"},{"type":"text","text":": At 35% VLT, daytime visibility is essentially unchanged. Night driving sees some reduction in ambient light but remains well within safe limits."}]}]}]},{"type":"horizontalRule"},{"type":"paragraph","content":[{"type":"text","text":"If you want to understand how our films compare across VLT, TSER, IR rejection, and UV protection, the "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/compare","target":"_blank","rel":"noopener noreferrer","class":null,"title":null}}],"text":"SUNKOOL comparison tool"},{"type":"text","text":" walks you through every product side by side. For questions about the right film for your car and your climate, "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/contact","target":"_blank","rel":"noopener noreferrer","class":null,"title":null}}],"text":"contact us"},{"type":"text","text":" — we''ll give you a straight answer."}]}]}'::jsonb,
